import type {Board} from './ScenarioBoard'
export type Values=Record<string,number|string>
export type Field={key:string;label:string;value:number|string;choices?:string[];step?:number;min?:number;max?:number}
export type Action={label:string;run:(v:Values)=>Board;explain:string}
export type WorkModel={fields:Field[];actions:Action[];source?:(v:Values)=>Board;kind?:'alert'}
const f=(key:string,label:string,value:number|string,choices?:string[]):Field=>({key,label,value,choices})
const n=(v:Values,k:string)=>Number(v[k]),sum=(a:number[])=>a.reduce((s,v)=>s+v,0)
const med=(a:number[])=>{const b=[...a].sort((a,b)=>a-b),m=Math.floor(b.length/2);return b.length%2?b[m]:(b[m-1]+b[m])/2}
const fmt=(x:unknown)=>typeof x==='number'?(Number.isFinite(x)?x.toLocaleString('ru-RU',{maximumFractionDigits:4}):'не определено'):String(x)
export const table=(columns:string[],rows:unknown[][]):Board=>({kind:'table',columns,rows:rows.map(r=>r.map(fmt))})
const action=(label:string,run:Action['run'],explain:string):Action=>({label,run,explain})
const calc=(fields:Field[],first:Action,second:Action):WorkModel=>({fields,actions:[first,second]})
const nums=(v:Values,keys:string[])=>keys.map(k=>n(v,k))
const rows=(v:Values)=>table(['Параметр','Значение'],Object.entries(v))
const series=(a:number[],prefix='x')=>a.map((v,i)=>f(prefix+i,`${prefix==='x'?'':`Набор ${prefix.toUpperCase()} · `}Образец ${i+1}`,v))
