const comparisons=(before:number[],after:number[])=>calc([...series(before,'a'),...series(after,'b')],action('Сопоставить по ID',v=>table(['ID','До','После','Совпадение'],before.map((_,i)=>[i+1,v['a'+i],v['b'+i],v['a'+i]===v['b'+i]?'да':'нет'])),'Значения сравниваются по одному и тому же ключу.'),action('Сверить итоги и различия',v=>table(['Проверка','До','После'],[['SUM',sum(before.map((_,i)=>n(v,'a'+i))),sum(after.map((_,i)=>n(v,'b'+i)))],['Несовпавших ID',before.filter((_,i)=>v['a'+i]!==v['b'+i]).length,'Совпавшая сумма не отменяет различий']]),'Контрольная сумма не заменяет сравнение строк.'))
const samples=(before:number[],after?:number[])=>after?calc([...series(before,'a'),...series(after,'b')],action('Отсортировать оба ряда',v=>table(['Ряд','Значения'],[['До',before.map((_,i)=>n(v,'a'+i)).sort((a,b)=>a-b).join(', ')],['После',after.map((_,i)=>n(v,'b'+i)).sort((a,b)=>a-b).join(', ')]]),'Каждый повтор сохраняется. Выбросы не удаляются автоматически.'),action('Вычислить медианы',v=>{const a=med(before.map((_,i)=>n(v,'a'+i))),b=med(after.map((_,i)=>n(v,'b'+i)));return table(['Медиана до, мс','Медиана после, мс','До / после'],[[a,b,a/b]])},'Ускорение относится к заданным данным и одинаковому способу измерения.')):calc(series(before),action('Отсортировать образцы',v=>table(['Позиция','Время, мс'],before.map((_,i)=>n(v,'x'+i)).sort((a,b)=>a-b).map((x,i)=>[i+1,x])),'Сортировка сохраняет все наблюдения.'),action('Вычислить медиану и среднее',v=>{const a=before.map((_,i)=>n(v,'x'+i));return table(['Медиана, мс','Среднее, мс','Наблюдений'],[[med(a),sum(a)/a.length,a.length]])},'Среднее реагирует на выброс; медиана выбирает середину упорядоченного ряда.'))
