export const initialValues=(model:WorkModel):Values=>Object.fromEntries(model.fields.map(f=>[f.key,f.value]))
export const sourceBoard=(model:WorkModel,values:Values)=>model.source?.(values)||table(['Исходный параметр','Значение'],model.fields.map(f=>[f.label,values[f.key]]))
export type MetricEvent={time:number;value:number}
export function alertTrace(values:Values,time:number,overrides:MetricEvent[]=[]){
 const events=[{time:0,value:1.2},{time:120,value:0.5},{time:180,value:1.2},...overrides].map((e,i)=>({...e,order:i})).sort((a,b)=>a.time-b.time||a.order-b.order)
 let active:number|null=null,value=1.2;const trace:{time:number;value:number;elapsed:number;state:string}[]=[]
 for(let t=0;t<=time;t+=30){for(const e of events.filter(e=>e.time===t)){value=e.value;if(value<=n(values,'threshold'))active=null;}if(value>n(values,'threshold'))active??=t;else active=null;const elapsed=active===null?0:t-active;trace.push({time:t,value,elapsed,state:active===null?'normal':elapsed>=n(values,'for')?'firing':'pending'})}
 return trace
}
